  if (cuTensorMapEncodeTiled(&mE2, CU_TENSOR_MAP_DATA_TYPE_FLOAT16, 2, emb16, dE, sE, bE2, es, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 432;
  cudaFuncSetAttribute(tc_h_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemDyn);
  const int n8 = B * kD / 8;
  emb_f16_kernel<<<(n8 + 255) / 256, 256, 0, stream>>>(emb, (uint4*)emb16, n8);
  OutPtrs op; for (int i = 0; i < 6; ++i) op.p[i] = outs[i];
  cudaLaunchConfig_t cfg = {}; cfg.gridDim = dim3(2 * (kN / (2 * kRows)) * p.nb); cfg.blockDim = dim3(kThreads);
  cfg.dynamicSmemBytes = p.stages * stageBytes + 1024; cfg.stream = stream;
  cudaLaunchAttribute at[1]; at[0].id = cudaLaunchAttributeClusterDimension; at[0].val.clusterDim.x = 2; at[0].val.clusterDim.y = 1; at[0].val.clusterDim.z = 1;
  cfg.attrs = at; cfg.numAttrs = 1;
  cudaLaunchKernelEx(&cfg, tc_h_kernel, W, mW, mE1, mE2, bias, op, p);
  return (int)cudaGetLastError();
}
